head.script:
scwin.vScrenID = "ULDSTF03704.xml";
///////// 1. 변수 및 선언 영역 /////////
scwin.mktTpCd = "";

// 코넥스(mktTpCd:6)일때 교육회사 링크 JLDFIL16502, JLDFIL16503 화면은 TOBE에서 사용안함(2026.06.12 유태연S)

///////// 2. 초기화 영역 /////////
scwin.onpageload = function () {
    //로드 서브미션 필요(교육회사, 그리드 조회)
    //dma_EduAppResultInfo
    //dlt_EduAppResultList

    scwin.mktTpCd = dma_EduAppResultInfo.get("mktTpCd");
    scwin.mktTpCd = "1";
    scwin.setDisclsEduApctTpCd(); // 구분 콤보박스 SET
    scwin.setGridHeader(); // 그리드 헤더 SET

    //처리결과 alert창 표출
    // var msg = '${ResultMsg}';
    // if (msg != '') {
    //     alert(msg);
    // }
};

///////// 3. 컴포넌트 이벤트 영역 /////////
scwin.search = function () {
    scwin.check();
    let url = "eduAppResult.do?method=searchRstEduApplication";
    $c.sbm.setAction(sbm_Search, url);
    $c.sbm.execute(sbm_Search);

    flag = true;
};

scwin.sbx_disclsEduApctTpCd_onviewchange = function (info) {
    scwin.change();
};

scwin.btn_Apply_onclick = function (e) {
    scwin.fn_Check();
};

scwin.btn_Excel_onclick = function (e) {
    scwin.excel_download();
};

///////// 5. 일반/업무 함수 영역 /////////
scwin.setDisclsEduApctTpCd = function () {
    if (scwin.mktTpCd === "1") {
        sbx_disclsEduApctTpCd.addItem("11", "[유가]공시책임자", 1);
        sbx_disclsEduApctTpCd.addItem("12", "[유가]공시담당자", 2);
    } else if (scwin.mktTpCd === "2") {
        sbx_disclsEduApctTpCd.addItem("41", "[코스닥]공시책임자", 1);
        sbx_disclsEduApctTpCd.addItem("42", "[코스닥]공시담당자", 2);
    } else if (scwin.mktTpCd === "6") {
        sbx_disclsEduApctTpCd.addItem("81", "[코넥스]공시책임자", 1);
        sbx_disclsEduApctTpCd.addItem("82", "[코넥스]공시대리인", 2);
    }

    sbx_disclsEduApctTpCd.setValue(dma_EduAppResultInfo.get("disclsEduApctTpCd"));
};

scwin.setGridHeader = function () {
    if (scwin.mktTpCd === "6") {
        grd_EduAppResultList.setColumnVisible("eduYn", true); //교육이수
        grd_EduAppResultList.setColumnVisible("jobtitlNm", true); //직위
        grd_EduAppResultList.setColumnVisible("chrgNm", true); //성명
        grd_EduAppResultList.setColumnVisible("birthDd", true); //생년월일
    } else if (scwin.mktTpCd === "1" || scwin.mktTpCd === "2") {
        grd_EduAppResultList.setColumnVisible("roomTpCd", true); //간담회 참석여부
        grd_EduAppResultList.setColumnVisible("eduPartcCnt", true); //교육참가 예상인원
    }
};

