scwin.change = function (code) {
    //TOBE : 필터로 대체
    dlt_EduScheduleList.removeColumnFilterAll();
    let disclsEduApctTpCd = sbx_disclsEduApctTpCd.getValue();
    if (disclsEduApctTpCd === "") disclsEduApctTpCd = " ";
    dlt_EduScheduleList.setColumnFilter({ type: "row", colIndex: "disclsEduApctTpCd", key: disclsEduApctTpCd, condition: "and", exactMatch: false });

    sbx_disclsEduCrsNm.setValue(dma_EduAppResultInfo.get("disclsEduApplSeq"));
};

scwin.excel_download = function () {
    check();
    const eduTp = sbx_disclsEduApctTpCd.getValue();

    if ("12" === eduTp || "42" === eduTp || "82" === eduTp) {	//공시책임자, 담당자에 따라 분기한다.
        form.method.setValue('searchRstEduExcelApplicationChg');
    } else {
        form.method.setValue('searchRstEduExcelApplication');
    }

    form.action = 'eduAppResult.do';
    form.SCREN_PROCES_TP_CD.setValue("07");
    form.submit();
};

